import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

solutions = []

# Test n from 2 to 6
for n in range(2, 7):
    # Test x starting from n+1. Let's check up to x=10 initially.
    # We might need to increase this range later if no solutions are found,
    # but for "small values", this should suffice for a first pass.
    for x in range(n + 1, 11):
        try:
            # Calculate R = x^n + x - 2
            R = x**n + x - 2

            if is_power_of_two(R):
                # R is a power of 2, so R = 2^k. We need to find k.
                k = int(math.log2(R))
                solutions.append((x, n, k))
        except OverflowError:
            # Stop searching for larger x if we hit overflow (unlikely for small constraints, but good practice)
            break

print("Found solutions (x, n, k):")
for sol in solutions:
    print(sol)

